// Sample input. Replace with your own export of Sort Feed results (manual copy).
return [{ json: {
  niche: 'personal finance for students',
  min_views: 10000000,
  videos_per_day: 10,
  start_date: '2026-10-01',
  own_avg_views: 40000,
  mega_viral_threshold_views: 1000000,
  references: [
    { page: '@pageA', url: 'https://www.instagram.com/reel/AAA111/', views: 12500000, hook: '3 money rules I wish I knew at 19' },
    { page: '@pageB', url: 'https://www.instagram.com/reel/BBB222/', views: 9800000, hook: 'Stop doing this with your first paycheck' },
    { page: '@pageA', url: 'https://www.instagram.com/reel/AAA111/?igsh=x', views: 12500000, hook: '3 money rules I wish I knew at 19' },
    { page: '@pageC', url: 'https://www.instagram.com/reel/CCC333/', views: 64000000, hook: 'The student budget that actually works' },
    { page: '@pageD', url: 'https://www.instagram.com/reel/DDD444/', views: 21000000, hook: 'Why your savings account is losing money' }
  ]
} }];

const items = $input.all();
if (!items.length) throw new Error('No input items');
return items.map(({ json: j }) => {
  const e = [];
  if (typeof j.niche !== 'string' || !j.niche.trim()) e.push('niche is required');
  if (!Number.isFinite(j.min_views) || j.min_views <= 0) e.push('min_views must be a positive number');
  if (!Number.isInteger(j.videos_per_day) || j.videos_per_day < 1 || j.videos_per_day > 50) e.push('videos_per_day must be an integer 1-50');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(j.start_date || '')) e.push('start_date must be YYYY-MM-DD');
  if (!Number.isFinite(j.own_avg_views) || !Number.isFinite(j.mega_viral_threshold_views)) e.push('own_avg_views and mega_viral_threshold_views must be numbers');
  if (!Array.isArray(j.references) || !j.references.length) e.push('references must be a non-empty array');
  else j.references.forEach((r, i) => {
    if (!/^https?:\/\//.test(r.url || '')) e.push('references[' + i + '].url must be http(s)');
    if (!Number.isFinite(r.views) || r.views < 0) e.push('references[' + i + '].views must be a non-negative number');
  });
  if (e.length) throw new Error('Invalid input: ' + e.join('; '));
  return { json: j };
});

const out = [];
const norm = u => { try { const x = new URL(u.trim()); return x.protocol + '//' + x.host.toLowerCase() + x.pathname.replace(/\/+$/, ''); } catch { return u.trim().split('?')[0].replace(/\/+$/, ''); } }; // host lowercased only; Instagram shortcodes are case-sensitive and preserved
const hash = s => { let x = 5381; for (const c of s) x = ((x << 5) + x + c.charCodeAt(0)) >>> 0; return x.toString(16); };
const addDays = (d, n) => { const t = new Date(d + 'T00:00:00Z'); t.setUTCDate(t.getUTCDate() + n); return t.toISOString().slice(0, 10); };
for (const { json: j } of $input.all()) {
  const seen = new Set();
  const unique = [];
  for (const r of j.references) { const k = norm(r.url); if (seen.has(k)) continue; seen.add(k); unique.push({ ...r, url_key: k }); }
  const shortlisted = unique.filter(r => r.views >= j.min_views).sort((a, b) => b.views - a.views);
  if (!shortlisted.length) throw new Error('No reference videos meet min_views=' + j.min_views + '; nothing queued');
  const offerTier = j.own_avg_views >= j.mega_viral_threshold_views ? 'mega_viral_low_ticket' : 'niche_higher_ticket';
  shortlisted.forEach((r, i) => out.push({ json: {
    row_id: hash(j.niche + '|' + r.url_key),
    niche: j.niche,
    rank: i + 1,
    page: r.page || '',
    url: r.url,
    views: r.views,
    hook: r.hook || '',
    production_date: addDays(j.start_date, Math.floor(i / j.videos_per_day)),
    status: 'to_record',
    offer_tier: offerTier,
    duplicates_removed: j.references.length - unique.length,
    excluded_below_threshold: unique.length - shortlisted.length,
    retargeting: 'MANUAL_HANDOFF: build a retargeting audience of engaged viewers in your ads manager'
  } }));
}
return out;
